<script setup lang="ts">
const route=useRoute();const config=useRuntimeConfig();const {data,error}=await useFetch<any>(`${config.public.apiBase}/products/${route.params.slug}`);const product=computed(()=>data.value?.data);
const { add, error: cartError } = useStorefrontCart();
const adding = ref(false);
const added = ref(false);
const selectedVariant = computed(() => product.value?.variants?.find((variant:any) => variant.is_default) || product.value?.variants?.[0]);
async function addToCart() { if (!selectedVariant.value) return; adding.value = true; added.value = false; try { await add(Number(selectedVariant.value.id), 1); added.value = true } catch { /* composable exposes the error */ } finally { adding.value = false } }
useSeoMeta({title:()=>product.value?`${product.value.name} | MADINA Scale`:'Product | MADINA Scale',description:()=>product.value?.short_description||'Explore weighing solutions from MADINA Scale.',ogTitle:()=>product.value?.name||'MADINA Scale'});
</script>
<template><main class="container py-12"><p v-if="error" class="surface p-6 text-red-700">Product not found or API unavailable.</p><div v-else-if="product" class="grid gap-10 md:grid-cols-2"><div class="surface aspect-square overflow-hidden p-6"><StorefrontImage :src="product.image_url" :alt="product.name" kind="product" label="Product Image" dimensions="1400 × 1400 px" ratio="1 / 1" :width="1400" :height="1400" /></div><div><p class="text-sm font-bold text-emerald-800">{{product.category}}</p><h1 class="mt-3 text-3xl font-extrabold">{{product.name}}</h1><p class="mt-5 text-2xl font-extrabold">{{product.price??'Contact for price'}}</p><p class="mt-5 leading-7 muted">{{product.description||product.short_description}}</p><div class="mt-8 flex flex-wrap items-center gap-3"><button class="btn-primary" :disabled="adding || !selectedVariant" @click="addToCart">{{ adding ? 'Adding…' : 'Add to cart' }}</button><NuxtLink to="/cart" class="rounded-full border border-emerald-900 px-5 py-3 font-bold text-emerald-950">View cart</NuxtLink></div><p v-if="added" class="mt-3 text-sm font-semibold text-emerald-800">Added to your cart successfully.</p><p v-if="cartError" class="mt-3 text-sm text-red-700">{{ cartError }}</p></div></div></main></template>
